import type { Soru } from "../sorular";

export const P09: Soru[] = [
  { id: "p09-001", k: "Vücut", s: "Sinir sisteminin bilgi taşıyan temel hücresine ne ad verilir?", d: "Nöron", y: ["Eritrosit", "Osteosit"], a: "Nöronlar bilgiyi elektriksel uyarılar ve kimyasal sinyallerle birbirine iletir." },
  { id: "p09-002", k: "Vücut", s: "Güncel sayımlara göre insan beyninde yaklaşık kaç nöron bulunur?", d: "Yaklaşık 86 milyar", y: ["Yaklaşık 86 milyon", "Yaklaşık 8 trilyon"], a: "2009'da yayımlanan bir sayım yöntemiyle insan beyninde yaklaşık 86 milyar nöron olduğu hesaplandı." },
  { id: "p09-003", k: "Vücut", s: "Yetişkin bir insan beyni yaklaşık ne kadar gelir?", d: "Yaklaşık 1,4 kilogram", y: ["Yaklaşık 300 gram", "Yaklaşık 5 kilogram"], a: "Yetişkin beyni ortalama 1,3-1,4 kilogram kadardır; vücut ağırlığının yaklaşık yüzde 2'si eder." },
  { id: "p09-004", k: "Vücut", s: "Beyin vücut ağırlığının yaklaşık %2'si kadardır. Dinlenirken vücudun enerjisinin ne kadarını kullanır?", d: "Yaklaşık %20", y: ["Yaklaşık %2", "Yaklaşık %60"], a: "Beyin çok küçük olmasına rağmen dinlenme hâlinde vücudun harcadığı enerjinin yaklaşık beşte birini tüketir." },
  { id: "p09-005", k: "Vücut", s: "Beynin iki yarımküresini birbirine bağlayan kalın sinir lifi demetinin adı nedir?", d: "Korpus kallozum", y: ["Hipotalamus", "Beyincik"], a: "Korpus kallozum yaklaşık 200 milyon sinir lifinden oluşur ve iki yarımküre arasında bilgi taşır." },
  { id: "p09-006", k: "Vücut", s: "Denge ve hareketlerin koordinasyonunda başlıca rol oynayan beyin bölümü hangisidir?", d: "Beyincik", y: ["Hipofiz", "Koku soğanı"], a: "Beyincik kafatasının arka alt kısmındadır; hareketleri düzgün ve dengeli hâle getirir." },
  { id: "p09-007", k: "Vücut", s: "Solunum ve kalp atışı gibi otomatik işlevleri düzenleyen beyin sapı bölümü hangisidir?", d: "Omurilik soğanı", y: ["Beyincik", "Görme korteksi"], a: "Omurilik soğanı (medulla oblongata) beyin sapının en alt kısmıdır ve yaşamsal refleksleri yönetir." },
  { id: "p09-008", k: "Vücut", s: "Birincil görme korteksi beynin hangi lobunda bulunur?", d: "Oksipital (art kafa) lob", y: ["Frontal (alın) lob", "Temporal (şakak) lob"], a: "Gözlerden gelen sinyaller beynin en arkasındaki oksipital lobda işlenir; görüntü aslında beynin arkasında oluşur." },
  { id: "p09-009", k: "Vücut", s: "Yeni anıların oluşmasında kilit rol oynayan, deniz atına benzetilen beyin yapısı hangisidir?", d: "Hipokampus", y: ["Amigdala", "Talamus"], a: "Hipokampus adını Yunancada deniz atı anlamına gelen kelimeden alır. Yeni bilgilerin kalıcı anıya dönüşmesinde önemlidir." },
  { id: "p09-010", k: "Vücut", s: "Korku tepkilerinde merkezi rol oynayan, badem biçimli beyin yapısı hangisidir?", d: "Amigdala", y: ["Hipokampus", "Epifiz bezi"], a: "Amigdala adını Yunancada badem anlamına gelen kelimeden alır; tehlikeyi fark etmede ve duygusal anılarda rol oynar." },
  { id: "p09-011", k: "Vücut", s: "Vücut sıcaklığını, açlık ve susuzluk hissini düzenleyen beyin bölgesi hangisidir?", d: "Hipotalamus", y: ["Beyincik", "Korpus kallozum"], a: "Hipotalamus küçük ama çok önemli bir bölgedir; vücudun termostatı gibi çalışır ve hormon sistemini de yönlendirir." },
  { id: "p09-012", k: "Vücut", s: "Planlama, karar verme ve dürtüleri kontrol etmede öne çıkan beyin lobu hangisidir?", d: "Frontal (alın) lob", y: ["Oksipital lob", "Parietal lob"], a: "Frontal lob, özellikle de ön kısmı olan prefrontal korteks, planlama ve öz denetim gibi işlevlerle ilişkilidir." },
  { id: "p09-013", k: "Vücut", s: "Konuşma üretimiyle ilişkilendirilen ve 1861'de tanımlanan beyin bölgesi hangisidir?", d: "Broca alanı", y: ["Wernicke alanı", "Görme korteksi"], a: "Fransız hekim Paul Broca, konuşamayan hastaların beyninde sol frontal lobdaki bu bölgenin hasarlı olduğunu gösterdi." },
  { id: "p09-014", k: "Vücut", s: "Dili anlamakla ilişkilendirilen, şakak lobundaki beyin bölgesi hangisidir?", d: "Wernicke alanı", y: ["Broca alanı", "Motor korteks"], a: "Carl Wernicke 1874'te bu bölgesi hasarlı hastaların akıcı konuşup söyleneni anlayamadığını tanımladı." },
  { id: "p09-015", k: "Vücut", s: "İki sinir hücresinin birbirine sinyal ilettiği bağlantı noktasına ne denir?", d: "Sinaps", y: ["Alveol", "Nefron"], a: "Sinapslarda sinyal çoğunlukla kimyasal maddelerle karşı hücreye aktarılır. Beyinde trilyonlarca sinaps vardır." },
  { id: "p09-016", k: "Vücut", s: "Nöronda sinyali hücre gövdesinden uzağa ileten uzun uzantıya ne ad verilir?", d: "Akson", y: ["Dendrit", "Kirpik"], a: "Akson, sinyali hücre gövdesinden başka hücrelere taşır. Bazı aksonlar bir metreden uzun olabilir." },
  { id: "p09-017", k: "Vücut", s: "Nöronun diğer hücrelerden sinyal alan dallı uzantılarına ne denir?", d: "Dendritler", y: ["Aksonlar", "Ribozomlar"], a: "Dendritler ağaç dallarına benzer; binlerce sinapstan gelen sinyalleri toplayıp hücre gövdesine iletir." },
  { id: "p09-018", k: "Vücut", s: "Aksonları saran ve sinyalin çok daha hızlı iletilmesini sağlayan yağlı kılıfın adı nedir?", d: "Miyelin kılıf", y: ["Hücre duvarı", "Kıkırdak"], a: "Miyelin bir yalıtkan gibi çalışır; sinyal kılıftaki boşluklar arasında atlayarak çok daha hızlı ilerler." },
  { id: "p09-019", k: "Vücut", s: "Bağışıklık sisteminin sinirlerdeki miyelin kılıfa zarar verdiği hastalık hangisidir?", d: "Multipl skleroz (MS)", y: ["Sıtma", "Kızamık"], a: "MS'te bağışıklık sistemi merkezi sinir sistemindeki miyeline saldırır; bu yüzden sinyal iletimi bozulur." },
  { id: "p09-020", k: "Vücut", s: "Merkezi sinir sistemi hangi yapılardan oluşur?", d: "Beyin ve omurilik", y: ["Beyin ve kalp", "Omurilik ve deri"], a: "Beyin ve omurilik merkezi sinir sistemini oluşturur; buradan çıkan sinirler ise çevresel sinir sistemidir." },
  { id: "p09-021", k: "Vücut", s: "Ödül ve motivasyon sistemiyle en çok ilişkilendirilen nörotransmitter hangisidir?", d: "Dopamin", y: ["Melatonin", "Histamin"], a: "Dopamin, beklenen bir ödül ya da beklenmedik iyi bir sonuçla ilgili sinyallerde önemli rol oynar." },
  { id: "p09-022", k: "Vücut", s: "Parkinson hastalığında hangi maddeyi üreten beyin hücreleri kaybedilir?", d: "Dopamin", y: ["Serotonin", "Melatonin"], a: "Parkinson'da orta beyindeki dopamin üreten nöronlar azalır; bu da titreme ve hareket yavaşlığına yol açar." },
  { id: "p09-023", k: "Vücut", s: "Sinirden kasa sinyal ileten kimyasal haberci hangisidir?", d: "Asetilkolin", y: ["Dopamin", "Melatonin"], a: "Sinir-kas kavşağında salgılanan asetilkolin, kas hücresine kasılma sinyalini verir." },
  { id: "p09-024", k: "Vücut", s: "Beyindeki başlıca uyarıcı nörotransmitter hangisidir?", d: "Glutamat", y: ["GABA", "Melatonin"], a: "Glutamat, beyindeki uyarıcı sinyallerin büyük kısmını taşır ve öğrenmede de önemli rol oynar." },
  { id: "p09-025", k: "Vücut", s: "Beyindeki başlıca baskılayıcı (inhibitör) nörotransmitter hangisidir?", d: "GABA", y: ["Glutamat", "Adrenalin"], a: "GABA nöronların ateşlenmesini azaltır; uyarı ile baskı arasındaki denge beynin sağlıklı çalışması için şarttır." },
  { id: "p09-026", k: "Vücut", s: "Tehlike anında \"savaş ya da kaç\" tepkisini başlatan sinir sistemi bölümü hangisidir?", d: "Sempatik sinir sistemi", y: ["Parasempatik sinir sistemi", "Somatik sinir sistemi"], a: "Sempatik sistem kalp atışını hızlandırır, göz bebeklerini büyütür ve vücudu ani harekete hazırlar." },
  { id: "p09-027", k: "Vücut", s: "Dinlenme ve sindirim sırasında baskın olan sinir sistemi bölümü hangisidir?", d: "Parasempatik sinir sistemi", y: ["Sempatik sinir sistemi", "Somatik sinir sistemi"], a: "Parasempatik sistem kalp atışını yavaşlatır ve sindirimi destekler; sempatik sistemin tersine çalışır." },
  { id: "p09-028", k: "Vücut", s: "Sıcak bir sobaya dokununca elini çekme refleksi ilk olarak nerede işlenir?", d: "Omurilikte", y: ["Frontal lobda", "Hipokampusta"], a: "Refleks yayı omurilikte kapanır, bu yüzden el çok hızlı çekilir. Acıyı bilinçli olarak biraz sonra hissederiz." },
  { id: "p09-029", k: "Vücut", s: "Beyni ve omuriliği saran koruyucu zarlara ne ad verilir?", d: "Meninksler (beyin zarları)", y: ["Plevra zarları", "Kornea katmanları"], a: "Beyin ve omuriliği üç katlı zarlar sarar. Bu zarların iltihaplanmasına menenjit denir." },
  { id: "p09-030", k: "Vücut", s: "Beyni ve omuriliği çevreleyip bir yastık gibi koruyan sıvı hangisidir?", d: "Beyin omurilik sıvısı", y: ["Safra", "Gözyaşı"], a: "Beyin omurilik sıvısı beyni darbelere karşı korur, onu yüzdürür ve atıkların uzaklaştırılmasına yardım eder." },
  { id: "p09-031", k: "Vücut", s: "Kandaki birçok maddenin beyne geçişini sınırlayan koruyucu yapıya ne denir?", d: "Kan-beyin bariyeri", y: ["Diyafram", "Kornea"], a: "Beyin damarlarının hücreleri birbirine sıkıca bağlıdır; birçok mikrop ve zararlı madde bu yüzden beyne kolayca geçemez." },
  { id: "p09-032", k: "Vücut", s: "Beynin en dışındaki kıvrımlı, gri madde katmanına ne ad verilir?", d: "Serebral korteks", y: ["Beyin sapı", "Omurilik soğanı"], a: "Serebral korteks düşünme, algı ve istemli hareket gibi üst düzey işlevlerin merkezidir." },
  { id: "p09-033", k: "Vücut", s: "Beyin yüzeyinin kıvrım kıvrım olmasının başlıca faydası nedir?", d: "Kafatasına daha geniş korteks sığdırır", y: ["Beyni darbelere karşı sertleştirir", "Beynin daha hafif olmasını sağlar"], a: "Kıvrımlar sayesinde geniş bir korteks yüzeyi sınırlı kafatası hacmine katlanarak sığar." },
  { id: "p09-034", k: "Vücut", s: "Beyindeki beyaz maddeye açık rengini veren nedir?", d: "Miyelinli aksonlar", y: ["Kan damarları", "Kalsiyum birikintisi"], a: "Beyaz madde çoğunlukla miyelinle kaplı aksonlardan oluşur; miyelinin yağlı yapısı ona açık rengini verir." },
  { id: "p09-035", k: "Vücut", s: "Sağ elin hareketlerini çoğunlukla beynin hangi kısmı kontrol eder?", d: "Sol yarımküre", y: ["Sağ yarımküre", "Beyin sapı"], a: "Hareket yolları beyin sapında çaprazlaşır; bu yüzden beynin sol yarısı vücudun sağ tarafını yönetir." },
  { id: "p09-036", k: "Vücut", s: "\"Beynimizin yalnızca %10'unu kullanırız\" sözü için doğru olan hangisi?", d: "Bir efsanedir", y: ["Kanıtlanmış bir bilgidir", "Yalnız uykuda geçerlidir"], a: "Beyin görüntüleme çalışmaları, beynin hemen her bölgesinin bir işlevi olduğunu ve gün içinde çalıştığını gösterir." },
  { id: "p09-037", k: "Vücut", s: "İnsanların \"sol beyinli\" ve \"sağ beyinli\" kişiliklere ayrıldığı fikri için ne söylenebilir?", d: "Bilimsel olarak desteklenmez", y: ["Beyin taramalarıyla kanıtlanmıştır", "Yalnız solaklar için doğrudur"], a: "Bazı işlevler bir yarımkürede daha baskındır, ama 1.000'den fazla kişinin taranması insanlarda baskın bir yarımküre bulmadı." },
  { id: "p09-038", k: "Vücut", s: "Beyin dokusunun kendisi ağrı hisseder mi?", d: "Hayır, ağrı reseptörü yoktur", y: ["Evet, en hassas dokudur", "Yalnız uykudayken hisseder"], a: "Beyin dokusunda ağrı reseptörü yoktur; bu yüzden bazı beyin ameliyatları hasta uyanıkken yapılabilir. Baş ağrısı zarlardan ve damarlardan kaynaklanır." },
  { id: "p09-039", k: "Vücut", s: "Beynin altında bulunan ve büyüme hormonu salgılayan bez hangisidir?", d: "Hipofiz", y: ["Tiroid", "Böbrek üstü bezi"], a: "Hipofiz bezi nohut büyüklüğündedir ama birçok bezi yönettiği için \"usta bez\" diye anılır." },
  { id: "p09-040", k: "Vücut", s: "Sinir hücreleri arasında sinyal taşıyan kimyasal maddelere genel olarak ne denir?", d: "Nörotransmitter", y: ["Antikor", "Enzim"], a: "Nörotransmitterler sinapsta salgılanır ve karşı hücredeki reseptörlere bağlanarak sinyali aktarır." },
  { id: "p09-041", k: "Vücut", s: "Sinir sinyali akson boyunca hangi biçimde ilerler?", d: "Elektriksel uyarı olarak", y: ["Ses dalgası olarak", "Işık parlaması olarak"], a: "Akson boyunca ilerleyen elektriksel uyarıya aksiyon potansiyeli denir; iyonların zardan geçişiyle oluşur." },
  { id: "p09-042", k: "Vücut", s: "En hızlı sinir lifleri sinyali yaklaşık hangi hızla iletir?", d: "Saniyede 100 metreyi aşkın", y: ["Saniyede yaklaşık 1 santimetre", "Işık hızına yakın"], a: "Kalın ve miyelinli lifler saniyede 100 metreyi geçebilir. İnce, miyelinsiz lifler ise saniyede yalnızca 1-2 metre hızdadır." },
  { id: "p09-043", k: "Vücut", s: "Beynin deneyimlerle bağlantılarını değiştirebilme yeteneğine ne ad verilir?", d: "Nöroplastisite", y: ["Fotosentez", "Osmoz"], a: "Nöroplastisite sayesinde öğreniriz; beyin hasarından sonra da bazı işlevler başka bölgelere geçebilir." },
  { id: "p09-044", k: "Vücut", s: "Doğrudan beyinden çıkan kafa sinirleri kaç çifttir?", d: "12 çift", y: ["31 çift", "5 çift"], a: "12 çift kafa siniri koku, görme, yüz hareketleri ve işitme gibi işlevleri taşır." },
  { id: "p09-045", k: "Vücut", s: "Omurilikten çıkan omurilik sinirleri kaç çifttir?", d: "31 çift", y: ["12 çift", "50 çift"], a: "Omurilikten 31 çift sinir çıkar ve vücudun büyük kısmıyla beyin arasında bilgi taşır." },
  { id: "p09-046", k: "Vücut", s: "İnmenin (felç) en sık görülen nedeni hangisidir?", d: "Beyne giden bir damarın tıkanması", y: ["Beyin zarlarının iltihaplanması", "Kafatasının kırılması"], a: "İnmelerin büyük çoğunluğu iskemiktir: bir pıhtı beyne giden kan akışını keser. Daha az sıklıkta damar yırtılır." },
  { id: "p09-047", k: "Vücut", s: "Alzheimer hastalığında beyinde biriken plakların ana proteini hangisidir?", d: "Beta-amiloid", y: ["Kolajen", "Keratin"], a: "Alzheimer'da beta-amiloid plakları ve tau proteini yumakları birikir, nöronlar giderek kaybolur." },
  { id: "p09-048", k: "Vücut", s: "Epilepsi nöbetlerinin temelinde ne vardır?", d: "Nöronların aşırı ve eş zamanlı ateşlenmesi", y: ["Kas liflerinin yırtılması", "Kandaki oksijen fazlalığı"], a: "Epilepside bir grup nöron birden ve düzensiz biçimde ateşlenir; bu elektriksel fırtına nöbete yol açar." },
  { id: "p09-049", k: "Vücut", s: "EEG (elektroensefalografi) neyi ölçer?", d: "Beynin elektriksel etkinliğini", y: ["Kan şekerini", "Kemik yoğunluğunu"], a: "EEG kafa derisine konan elektrotlarla beyin dalgalarını kaydeder; uyku ve epilepsi çalışmalarında çok kullanılır." },
  { id: "p09-050", k: "Vücut", s: "İnsan beyninin elektriksel etkinliğini ilk kez kaydeden bilim insanı kimdir?", d: "Hans Berger", y: ["Wilhelm Röntgen", "Sigmund Freud"], a: "Alman psikiyatrist Hans Berger insanda ilk EEG kaydını 1924'te yaptı ve 1929'da yayımladı." },
  { id: "p09-051", k: "Vücut", s: "fMRI beyin etkinliğini dolaylı olarak neyi izleyerek ölçer?", d: "Kan oksijenindeki değişimleri", y: ["Beyin sıcaklığını", "Kafatası kalınlığını"], a: "Çalışan bölgeye daha fazla oksijenli kan gelir. fMRI bu değişimi algılayarak hangi bölgelerin etkin olduğunu gösterir." },
  { id: "p09-052", k: "Vücut", s: "Nöronları destekleyen, besleyen ve koruyan hücrelere genel olarak ne denir?", d: "Glia hücreleri", y: ["Trombositler", "Osteoblastlar"], a: "Glia hücreleri miyelin üretir, atıkları temizler ve nöronların çevresini düzenler." },
  { id: "p09-053", k: "Vücut", s: "Güncel sayımlara göre insan beyninde glia hücresi sayısı nörona oranla nasıldır?", d: "Kabaca bire bir", y: ["Yaklaşık on kat fazla", "Yaklaşık yüz kat fazla"], a: "Glianın nörondan on kat fazla olduğu uzun süre tekrarlandı. Güncel sayımlar oranın kabaca bire bir olduğunu gösteriyor." },
  { id: "p09-054", k: "Vücut", s: "Beyin sapı beyni hangi yapıya bağlar?", d: "Omuriliğe", y: ["Göz kürelerine", "Kulak kemiklerine"], a: "Beyin sapı beyinle omurilik arasındaki köprüdür; solunum ve uyanıklık gibi temel işlevleri de düzenler." },
  { id: "p09-055", k: "Vücut", s: "Koku dışındaki duyu sinyallerini kortekse aktaran \"aktarma istasyonu\" hangisidir?", d: "Talamus", y: ["Hipofiz", "Amigdala"], a: "Görme, işitme ve dokunma sinyalleri kortekse ulaşmadan önce talamustan geçer. Koku ise doğrudan koku soğanından ilerler." },
  { id: "p09-056", k: "Vücut", s: "Dokunma bilgisinin işlendiği birincil duyu korteksi hangi lobdadır?", d: "Parietal (yan kafa) lob", y: ["Oksipital lob", "Temporal lob"], a: "Birincil somatosensoriyel korteks parietal lobun ön kısmındadır; vücudun her bölgesi burada haritalanmıştır." },
  { id: "p09-057", k: "Vücut", s: "Birincil işitme korteksi beynin hangi lobunda bulunur?", d: "Temporal (şakak) lob", y: ["Oksipital lob", "Frontal lob"], a: "Kulaktan gelen sinyaller şakak lobunun üst kısmındaki işitme korteksinde işlenir." },
  { id: "p09-058", k: "Vücut", s: "Duyu korteksinde boyutlarına oranla en geniş alanı kaplayan vücut bölgeleri hangileridir?", d: "Eller ve dudaklar", y: ["Sırt ve omuzlar", "Uyluk ve baldır"], a: "Beyindeki vücut haritası orantısızdır: hassas eller, parmaklar ve dudaklar çok geniş yer kaplar." },
  { id: "p09-059", k: "Vücut", s: "1848'de kafasından demir çubuk geçtiği hâlde yaşayan ve kişiliği değiştiği bildirilen işçi kimdir?", d: "Phineas Gage", y: ["Henry Molaison", "Paul Broca"], a: "Gage'in frontal lobu ağır hasar gördü. Vakası, bu bölgenin kişilik ve davranışla ilişkisine dair erken bir ipucu oldu." },
  { id: "p09-060", k: "Vücut", s: "Sinir sisteminin ayrı ayrı hücrelerden oluştuğunu gösteren, modern nörobilimin babası sayılan bilim insanı kimdir?", d: "Santiago Ramón y Cajal", y: ["Charles Darwin", "Robert Koch"], a: "İspanyol Cajal, nöronları ayrıntılı çizimleriyle tanımladı ve 1906 Nobel Ödülü'nü Camillo Golgi ile paylaştı." },
  { id: "p09-061", k: "Vücut", s: "Nöronları tek tek siyaha boyayıp görünür kılan yöntemi geliştiren İtalyan bilim insanı kimdir?", d: "Camillo Golgi", y: ["Luigi Galvani", "Alessandro Volta"], a: "Golgi'nin gümüş boyama yöntemi 1873'te geliştirildi; Cajal bu yöntemle nöronların ayrıntılı haritasını çıkardı." },
  { id: "p09-062", k: "Vücut", s: "Vücudun en uzun ve en kalın siniri hangisidir?", d: "Siyatik sinir", y: ["Görme siniri", "Yüz siniri"], a: "Siyatik sinir belin alt kısmından başlar ve bacak boyunca ayağa kadar uzanır." },
  { id: "p09-063", k: "Vücut", s: "Beyinden çıkıp kalp ve sindirim organlarına kadar uzanan, adı \"gezgin\" anlamına gelen sinir hangisidir?", d: "Vagus siniri", y: ["Görme siniri", "İşitme siniri"], a: "Vagus siniri onuncu kafa siniridir ve parasempatik sistemin en önemli yoludur." },
  { id: "p09-064", k: "Vücut", s: "Kurbağa bacaklarını elektrikle seğirterek \"hayvansal elektrik\" fikrini ortaya atan 18. yüzyıl bilgini kimdir?", d: "Luigi Galvani", y: ["Alessandro Volta", "Michael Faraday"], a: "Galvani'nin deneyleri sinir ve kasların elektrikle çalıştığı anlayışının başlangıcı oldu." },
  { id: "p09-065", k: "Vücut", s: "Sinirlerin kimyasal madde salgılayarak iletişim kurduğunu 1921'de kurbağa kalbiyle gösteren bilim insanı kimdir?", d: "Otto Loewi", y: ["Luigi Galvani", "Ivan Pavlov"], a: "Loewi, uyarılan vagus sinirinin salgıladığı maddenin ikinci bir kalbi de yavaşlattığını gösterdi. Bu madde asetilkolin çıktı." },
  { id: "p09-066", k: "Vücut", s: "Hodgkin ve Huxley sinir sinyalinin nasıl oluştuğunu hangi hayvanın dev aksonu üzerinde çözdü?", d: "Kalamar", y: ["Kurbağa", "Fare"], a: "Kalamarın dev aksonu elektrot sokulabilecek kadar kalındır. Bu çalışma 1963'te Nobel Ödülü getirdi." },
  { id: "p09-067", k: "Vücut", s: "Sinir sinyalinin oluşmasında hücre zarından geçen başlıca iki iyon hangileridir?", d: "Sodyum ve potasyum", y: ["Demir ve çinko", "Bakır ve iyot"], a: "Sodyum hücreye girince sinyal başlar, potasyum çıkınca zar eski hâline döner. Bu dalga akson boyunca ilerler." },
  { id: "p09-068", k: "Vücut", s: "Ağrı yaratan uyaranları algılayan duyu reseptörlerine ne ad verilir?", d: "Nosiseptörler", y: ["Fotoreseptörler", "Kemoreseptörler"], a: "Nosiseptörler doku hasarına yol açabilecek basınç, ısı ya da kimyasalları algılayıp omuriliğe sinyal gönderir." },
  { id: "p09-069", k: "Vücut", s: "Retinada renkleri algılayan ışık reseptörü hücreler hangileridir?", d: "Koni hücreleri", y: ["Çubuk hücreleri", "Tüylü hücreler"], a: "Koniler parlak ışıkta çalışır ve renk görmeyi sağlar; en yoğun bulundukları yer retinanın merkezidir." },
  { id: "p09-070", k: "Vücut", s: "Loş ışıkta görmemizi sağlayan retina hücreleri hangileridir?", d: "Çubuk hücreleri", y: ["Koni hücreleri", "Melanositler"], a: "Çubuklar ışığa çok duyarlıdır ama renk ayırt etmez; bu yüzden karanlıkta renkler soluk görünür." },
  { id: "p09-071", k: "Vücut", s: "Normal renk görüşüne sahip bir insanın retinasında kaç tip koni hücresi bulunur?", d: "Üç", y: ["İki", "Yedi"], a: "Kısa, orta ve uzun dalga boylarına duyarlı üç koni tipi vardır; beyin bunların sinyallerini karşılaştırarak rengi oluşturur." },
  { id: "p09-072", k: "Vücut", s: "Bir insan retinasında yaklaşık kaç çubuk hücresi bulunur?", d: "Yaklaşık 100 milyondan fazla", y: ["Yaklaşık 10 bin", "Yaklaşık 10 milyar"], a: "Retinada 100 milyonu aşkın çubuk ve yaklaşık 6 milyon koni hücresi bulunur." },
  { id: "p09-073", k: "Vücut", s: "Gözümüzde neden bir kör nokta vardır?", d: "Görme sinirinin çıktığı yerde reseptör yoktur", y: ["Göz merceği orada çok kalındır", "Kirpikler o bölgeye gölge düşürür"], a: "Görme sinirinin gözden çıktığı noktada çubuk ya da koni yoktur. Beyin bu boşluğu çevredeki görüntüyle doldurur." },
  { id: "p09-074", k: "Vücut", s: "Loş bir ortama girdiğimizde göz bebeklerimize ne olur?", d: "Büyür", y: ["Küçülür", "Hiç değişmez"], a: "Göz bebeği karanlıkta büyüyerek göze daha fazla ışık alır, parlak ışıkta ise küçülür." },
  { id: "p09-075", k: "Vücut", s: "Göz bebeğinin boyutunu ayarlayan, gözün renkli kısmına ne ad verilir?", d: "İris", y: ["Kornea", "Retina"], a: "İris, kas lifleri sayesinde göz bebeğini daraltıp genişletir; göz rengimizi de o belirler." },
  { id: "p09-076", k: "Vücut", s: "Gözün en önündeki saydam, kubbe biçimli tabakaya ne denir?", d: "Kornea", y: ["Retina", "İris"], a: "Kornea gözün ön penceresidir. İçinde kan damarı yoktur; oksijenin bir kısmını doğrudan havadan alır." },
  { id: "p09-077", k: "Vücut", s: "Gözde ışığı en çok kıran yapı hangisidir?", d: "Kornea", y: ["Göz merceği", "İris"], a: "Gözün toplam odaklama gücünün yaklaşık üçte ikisi korneadan gelir; mercek ise ince ayarı yapar." },
  { id: "p09-078", k: "Vücut", s: "Retinaya düşen görüntü nasıldır?", d: "Ters ve küçültülmüş", y: ["Düz ve büyütülmüş", "Yalnız siyah-beyaz"], a: "Göz bir kamera gibi çalışır ve retinada ters görüntü oluşur. Beyin bunu yorumlayarak dünyayı düz algılamamızı sağlar." },
  { id: "p09-079", k: "Vücut", s: "Retinada en keskin görmeyi sağlayan küçük çukura ne ad verilir?", d: "Fovea", y: ["Kör nokta", "Göz bebeği"], a: "Fovea koni hücreleriyle doludur. Bir şeye doğrudan baktığımızda görüntüsü tam bu noktaya düşer." },
  { id: "p09-080", k: "Vücut", s: "Miyop bir gözde uzaktaki nesnelerin görüntüsü nerede odaklanır?", d: "Retinanın önünde", y: ["Retinanın arkasında", "Tam retinanın üzerinde"], a: "Miyopide göz küresi genellikle biraz uzundur; görüntü retinaya ulaşmadan odaklanır ve uzak bulanık görünür." },
  { id: "p09-081", k: "Vücut", s: "Miyopiyi düzeltmek için hangi tür gözlük camı kullanılır?", d: "Iraksak (kenarları kalın) mercek", y: ["Yakınsak (ortası kalın) mercek", "Düz cam"], a: "Iraksak mercek ışığı biraz dağıtır; böylece odak noktası geriye, retinanın üzerine kayar." },
  { id: "p09-082", k: "Vücut", s: "Hipermetropiyi düzeltmek için hangi tür mercek kullanılır?", d: "Yakınsak (ortası kalın) mercek", y: ["Iraksak (kenarları kalın) mercek", "Prizma"], a: "Hipermetropide görüntü retinanın arkasında odaklanır. Yakınsak mercek ışığı toplayarak odağı öne çeker." },
  { id: "p09-083", k: "Vücut", s: "40'lı yaşlardan sonra yakını görmenin zorlaşmasının başlıca nedeni nedir?", d: "Göz merceğinin esnekliğini yitirmesi", y: ["Retinanın incelmesi", "Korneanın büyümesi"], a: "Bu duruma presbiyopi denir. Sertleşen mercek yakına odaklanmak için yeterince şekil değiştiremez." },
  { id: "p09-084", k: "Vücut", s: "Katarakt, gözün hangi kısmının bulanıklaşmasıdır?", d: "Göz merceğinin", y: ["Korneanın", "Retinanın"], a: "Kataraktta normalde saydam olan mercek bulanıklaşır. Ameliyatta bulanık mercek yapay bir mercekle değiştirilir." },
  { id: "p09-085", k: "Vücut", s: "Glokom (göz tansiyonu) başlıca hangi yapıya zarar verir?", d: "Görme sinirine", y: ["Göz merceğine", "Gözyaşı bezine"], a: "Glokomda görme siniri yavaş yavaş hasar görür; çoğu zaman göz içi basıncının yüksekliğiyle ilişkilidir." },
  { id: "p09-086", k: "Vücut", s: "Kırmızı-yeşil renk körlüğü erkeklerde neden çok daha sık görülür?", d: "İlgili genler X kromozomunda", y: ["Erkeklerde koni hücresi olmaz", "Testosteron renkleri soldurur"], a: "Erkeklerde tek X kromozomu vardır; buradaki bir kusuru dengeleyecek ikinci kopya yoktur." },
  { id: "p09-087", k: "Vücut", s: "Kendi renk körlüğünü 1794'te bilimsel olarak tanımlayan İngiliz kimyacı kimdir?", d: "John Dalton", y: ["Isaac Newton", "Michael Faraday"], a: "Dalton kendisinin ve kardeşinin renk algısını inceledi. Renk körlüğüne bu yüzden bazı dillerde daltonizm denir." },
  { id: "p09-088", k: "Vücut", s: "Renk körlüğü testlerinde kullanılan noktalı daire levhalarını geliştiren Japon göz hekimi kimdir?", d: "Shinobu Ishihara", y: ["Kikunae Ikeda", "Hideyo Noguchi"], a: "Ishihara levhaları 1917'de yayımlandı ve hâlâ kırmızı-yeşil renk körlüğü taramasında yaygın biçimde kullanılır." },
  { id: "p09-089", k: "Vücut", s: "Gözyaşında bulunan ve bazı bakterilerin duvarını parçalayan enzim hangisidir?", d: "Lizozim", y: ["Amilaz", "Pepsin"], a: "Lizozimi 1922'de Alexander Fleming keşfetti; gözyaşı, tükürük ve anne sütünde bulunur." },
  { id: "p09-090", k: "Vücut", s: "Bir yetişkin dakikada ortalama kaç kez göz kırpar?", d: "Yaklaşık 10-20 kez", y: ["Yaklaşık 1-2 kez", "Yaklaşık 100 kez"], a: "Göz kırpma korneayı nemlendirir ve temizler. Ekrana dikkatle bakarken kırpma sıklığı belirgin biçimde azalır." },
  { id: "p09-091", k: "Vücut", s: "Görme sinirlerinin beyne giderken kısmen çaprazlaştığı noktaya ne ad verilir?", d: "Optik kiyazma", y: ["Fovea", "Koklea"], a: "Optik kiyazmada her iki gözün iç yarısından gelen lifler karşı tarafa geçer. Böylece görme alanının sol yarısı sağ beyinde işlenir." },
  { id: "p09-092", k: "Vücut", s: "İnsan gözünün görebildiği ışığın dalga boyu aralığı yaklaşık nedir?", d: "400-700 nanometre", y: ["4-7 nanometre", "4.000-7.000 nanometre"], a: "Görünür ışık yaklaşık 400 nanometrede mordan 700 nanometrede kırmızıya uzanır. Morötesi ve kızılötesini göremeyiz." },
  { id: "p09-093", k: "Vücut", s: "Retinadaki ışığa duyarlı pigment rodopsinin yapımı için hangi vitamin gerekir?", d: "A vitamini", y: ["C vitamini", "K vitamini"], a: "Rodopsin, A vitamininden türeyen retinal molekülünü içerir. Işık bu molekülün şeklini değiştirerek görmeyi başlatır." },
  { id: "p09-094", k: "Vücut", s: "A vitamini eksikliğinin bilinen erken belirtilerinden biri hangisidir?", d: "Gece körlüğü", y: ["Renk körlüğü", "Şaşılık"], a: "A vitamini eksikliğinde çubuk hücreleri yeterli rodopsin üretemez; loş ışıkta görmek zorlaşır." },
  { id: "p09-095", k: "Vücut", s: "Gözün beyaz kısmını oluşturan sert dış tabakaya ne denir?", d: "Sklera", y: ["Kornea", "Retina"], a: "Sklera göz küresini saran dayanıklı bir tabakadır; önde saydam korneayla devam eder." },
  { id: "p09-096", k: "Vücut", s: "Mavi gözlerin rengi neden kaynaklanır?", d: "İriste az melanin ve ışığın saçılması", y: ["İristeki mavi pigment", "İristeki çok yoğun melanin"], a: "İnsan gözünde mavi pigment yoktur. İrisin ön katmanında melanin azsa ışık saçılır ve göz mavi görünür." },
  { id: "p09-097", k: "Vücut", s: "LASIK gibi lazer göz ameliyatları gözün hangi kısmını yeniden şekillendirir?", d: "Korneayı", y: ["Göz merceğini", "Retinayı"], a: "Lazer korneanın kavisini değiştirerek ışığın retinaya doğru odaklanmasını sağlar." },
  { id: "p09-098", k: "Vücut", s: "Okuma gözlükleri ilk kez nerede ve ne zaman ortaya çıktı?", d: "13. yüzyıl sonunda İtalya'da", y: ["Antik Mısır'da", "18. yüzyılda İngiltere'de"], a: "İlk gözlüklerin 1280'li yıllarda İtalya'da yapıldığı kabul edilir; yakını görmeyi kolaylaştıran merceklerdi." },
  { id: "p09-099", k: "Vücut", s: "Görmenin, nesnelerden göze gelen ışıkla gerçekleştiğini savunan 11. yüzyıl bilgini kimdir?", d: "İbn-i Heysem", y: ["İbn-i Sina", "Galen"], a: "İbn-i Heysem, Kitabü'l-Menazır adlı eserinde gözden ışın çıktığı fikrini reddetti ve deneylerle optiği inceledi." },
  { id: "p09-100", k: "Vücut", s: "Yakındaki bir nesneye bakarken göz odağını nasıl ayarlar?", d: "Merceğin şekli değişir", y: ["Göz küresi uzar", "Kornea yer değiştirir"], a: "Yakına bakarken mercek çevresindeki kaslar sayesinde daha yuvarlak hâle gelir. Buna uyum (akomodasyon) denir." },
  { id: "p09-101", k: "Vücut", s: "Derinliği ve uzaklığı algılamamıza en çok ne yardım eder?", d: "İki gözün biraz farklı görüntüleri", y: ["Göz kırpma sıklığı", "Göz rengi"], a: "İki göz dünyayı biraz farklı açılardan görür. Beyin bu farkı birleştirerek üç boyutlu algı oluşturur." },
  { id: "p09-102", k: "Vücut", s: "Orta kulaktaki üç küçük kemiğin görevi nedir?", d: "Sesi iç kulağa iletip güçlendirmek", y: ["Vücudun dengesini sağlamak", "Kulak kiri üretmek"], a: "Çekiç, örs ve üzengi kemikleri kulak zarının titreşimini iç kulağa aktarır ve bu sırada basıncı artırır." },
  { id: "p09-103", k: "Vücut", s: "Ses titreşimlerini sinir sinyaline çeviren, salyangoz biçimli iç kulak yapısı hangisidir?", d: "Koklea", y: ["Kulak zarı", "Östaki borusu"], a: "Koklea sıvı dolu, sarmal bir kanaldır. İçindeki tüylü hücreler titreşimi elektrik sinyaline dönüştürür." },
  { id: "p09-104", k: "Vücut", s: "Kokleada sesi algılayan duyu hücrelerine ne ad verilir?", d: "Tüylü hücreler", y: ["Koni hücreleri", "Tat hücreleri"], a: "Tüylü hücrelerin üstündeki ince uzantılar titreşimle eğilir ve hücre sinyal üretir." },
  { id: "p09-105", k: "Vücut", s: "İnsan iç kulağındaki tüylü hücreler hasar görünce ne olur?", d: "Yenilenmezler, kayıp kalıcıdır", y: ["Birkaç haftada yenilenirler", "Uykuda kendiliğinden onarılırlar"], a: "Kuşlarda bu hücreler yenilenebilir, ama insanlarda ve diğer memelilerde kaybolan tüylü hücreler geri gelmez." },
  { id: "p09-106", k: "Vücut", s: "Genç ve sağlıklı bir insanın duyabildiği ses frekansı aralığı yaklaşık nedir?", d: "20-20.000 Hz", y: ["2-2.000 Hz", "200-200.000 Hz"], a: "İnsan kulağı yaklaşık 20 hertzden 20.000 hertze kadar sesleri duyar. Üst sınır yaşla birlikte düşer." },
  { id: "p09-107", k: "Vücut", s: "Yaşlandıkça önce hangi sesleri duyma yeteneğimiz azalır?", d: "Tiz (yüksek frekanslı) sesleri", y: ["Pes (alçak frekanslı) sesleri", "Orta frekanslı sesleri"], a: "Yaşa bağlı işitme kaybı genellikle yüksek frekanslardan başlar; bu yüzden ince sesler önce zor duyulur." },
  { id: "p09-108", k: "Vücut", s: "Orta kulağı boğaza bağlayan ve basıncı dengeleyen kanalın adı nedir?", d: "Östaki borusu", y: ["Dış kulak yolu", "Koklea"], a: "Yutkunurken ya da esnerken Östaki borusu açılır ve orta kulaktaki basınç dış basınçla eşitlenir." },
  { id: "p09-109", k: "Vücut", s: "Uçak inişe geçerken kulakların tıkanmasının nedeni nedir?", d: "Kulak zarının iki yanındaki basınç farkı", y: ["Kulak kirinin donması", "Motor sesinin artması"], a: "Dış basınç hızla değişince kulak zarı gerilir. Yutkunmak Östaki borusunu açarak basıncı eşitlemeye yardım eder." },
  { id: "p09-110", k: "Vücut", s: "İç kulakta başın dönme hareketlerini algılayan yapılar hangileridir?", d: "Yarım daire kanalları", y: ["Kulak kepçesi", "Örs kemiği"], a: "Her kulakta birbirine dik üç yarım daire kanalı vardır. Baş dönünce içlerindeki sıvı hareket eder ve dengeyi bildirir." },
  { id: "p09-111", k: "Vücut", s: "Her bir iç kulakta kaç tane yarım daire kanalı bulunur?", d: "Üç", y: ["Bir", "Beş"], a: "Üç kanal üç ayrı düzlemde konumlanır; böylece başın her yöndeki dönüşü algılanır." },
  { id: "p09-112", k: "Vücut", s: "İç kulakta yer çekimini ve doğrusal hızlanmayı algılamaya yardım eden küçük kristaller neden yapılmıştır?", d: "Kalsiyum karbonat", y: ["Sodyum klorür", "Demir oksit"], a: "Otolit denen bu kristaller jel bir tabakanın üstünde durur. Baş eğilince kayarak altlarındaki tüylü hücreleri uyarır." },
  { id: "p09-113", k: "Vücut", s: "Taşıt tutmasının en yaygın kabul gören açıklaması nedir?", d: "Gözler ile iç kulağın çelişen bilgileri", y: ["Mide asidinin artması", "Kandaki oksijenin azalması"], a: "Araç içinde kitap okurken göz hareketsizlik, iç kulak hareket bildirir. Beynin bu çelişkiye tepkisi mide bulantısına yol açar." },
  { id: "p09-114", k: "Vücut", s: "Hızla dönüp aniden durunca dünya dönüyormuş gibi gelmesinin nedeni nedir?", d: "İç kulaktaki sıvının hareketi sürer", y: ["Kan beyne hücum eder", "Göz merceği yerinden kayar"], a: "Durduktan sonra yarım daire kanallarındaki sıvı bir süre dönmeye devam eder; beyin hâlâ dönüyormuşuz gibi sinyal alır." },
  { id: "p09-115", k: "Vücut", s: "Sesin şiddetini (yüksekliğini) ölçmek için hangi birim kullanılır?", d: "Desibel", y: ["Hertz", "Lümen"], a: "Desibel logaritmik bir ölçektir: yaklaşık her 10 desibellik artış, ses şiddetinin 10 kat artması demektir." },
  { id: "p09-116", k: "Vücut", s: "Bir sesin ince ya da kalın olmasını belirleyen frekansın birimi nedir?", d: "Hertz", y: ["Desibel", "Newton"], a: "Hertz saniyedeki titreşim sayısını gösterir. Frekans arttıkça ses daha ince (tiz) duyulur." },
  { id: "p09-117", k: "Vücut", s: "Günde 8 saat maruz kalındığında işitmeye zarar vermeye başladığı kabul edilen ses düzeyi yaklaşık kaçtır?", d: "85 desibel", y: ["30 desibel", "50 desibel"], a: "Yaygın kabul gören sınır 8 saat için 85 desibeldir. Ses yükseldikçe güvenli süre hızla kısalır." },
  { id: "p09-118", k: "Vücut", s: "Kulak kirinin vücuttaki görevi nedir?", d: "Kulak yolunu korur ve temizler", y: ["Sesi yükseltir", "Dengeyi sağlar"], a: "Kulak kiri tozu ve mikropları tutar, kulak yolunu nemli tutar. Çene hareketleriyle kendiliğinden dışarı doğru ilerler." },
  { id: "p09-119", k: "Vücut", s: "Dışarıda ses yokken kulakta çınlama ya da uğultu duyulmasına ne denir?", d: "Tinnitus", y: ["Vertigo", "Anosmi"], a: "Tinnitus çoğunlukla gürültüye maruz kalma ya da yaşa bağlı işitme kaybıyla ilişkilidir." },
  { id: "p09-120", k: "Vücut", s: "İşitme sinirini elektrikle uyararak ağır işitme kaybı olanlara ses algısı kazandıran cihaz hangisidir?", d: "Koklear implant", y: ["Kalp pili", "Kontakt lens"], a: "Koklear implant, sesi işleyip zarar görmüş tüylü hücrelerin yerine işitme sinirini doğrudan uyarır." },
  { id: "p09-121", k: "Vücut", s: "Kendi sesimizi kayıtta neden farklı duyarız?", d: "Konuşurken sesimizi kemik yoluyla da duyarız", y: ["Mikrofonlar sesi her zaman bozar", "Kulak kiri sesi değiştirir"], a: "Konuşurken ses kafatası kemikleriyle de iç kulağa ulaşır ve daha kalın duyulur. Kayıtta yalnız havadan gelen sesi duyarız." },
  { id: "p09-122", k: "Vücut", s: "Bir sesin hangi yönden geldiğini bulmamıza en çok ne yardım eder?", d: "Sesin iki kulağa varışındaki fark", y: ["Göz hareketleri", "Kulak kirinin miktarı"], a: "Beyin sesin iki kulağa ulaşma zamanı ve şiddeti arasındaki çok küçük farkları karşılaştırarak yönü hesaplar." },
  { id: "p09-123", k: "Vücut", s: "Orta kulak iltihabı çocuklarda neden daha sık görülür?", d: "Östaki boruları daha kısa ve yataydır", y: ["Kulak zarları daha kalındır", "Kulak kiri üretmezler"], a: "Çocuklarda Östaki borusu kısa ve yatay olduğundan boğazdaki mikroplar orta kulağa daha kolay ulaşır." },
  { id: "p09-124", k: "Vücut", s: "Dilin belirli bölgelerinin yalnız tek bir tadı algıladığını gösteren \"dil haritası\" için ne doğrudur?", d: "Yanlıştır, tatlar dilin her yerinde algılanır", y: ["Doğrudur, tatlı yalnız uçta algılanır", "Yalnız çocuklarda geçerlidir"], a: "Dil haritası 1901 tarihli bir Alman çalışmasının yanlış yorumlanmasından doğdu. Tat tomurcukları her temel tadı algılayabilir." },
  { id: "p09-125", k: "Vücut", s: "Tatlı, ekşi, tuzlu ve acıya eklenen beşinci temel tat hangisidir?", d: "Umami", y: ["Baharatlı", "Metalik"], a: "Umami, et suyu ve olgun domates gibi yiyeceklerdeki doyurucu lezzettir. Japonca \"lezzetli\" anlamına gelir." },
  { id: "p09-126", k: "Vücut", s: "Umami tadını 1908'de tanımlayan Japon kimyacı kimdir?", d: "Kikunae Ikeda", y: ["Shinobu Ishihara", "Hideyo Noguchi"], a: "Ikeda, kombu yosunu suyunun lezzetini glutamata bağladı. Umaminin ayrı bir tat olarak kabulü ise 2000'lerde reseptörünün bulunmasıyla güçlendi." },
  { id: "p09-127", k: "Vücut", s: "Umami tadını esas olarak hangi madde verir?", d: "Glutamat", y: ["Glikoz", "Sitrik asit"], a: "Glutamat bir amino asittir; peynir, et suyu, mantar ve domates gibi yiyeceklerde doğal olarak bulunur." },
  { id: "p09-128", k: "Vücut", s: "Acı biberin ağzı yakan hissini hangi duyu reseptörleri algılar?", d: "Isı ve ağrı reseptörleri", y: ["Tatlı reseptörleri", "Koku reseptörleri"], a: "Biberin yakıcılığı teknik olarak bir tat değildir. Kapsaisin, sıcaklık ve ağrıyı algılayan reseptörleri uyarır." },
  { id: "p09-129", k: "Vücut", s: "Acı biberi yakıcı yapan madde hangisidir?", d: "Kapsaisin", y: ["Kafein", "Mentol"], a: "Kapsaisin, ağızdaki ısıya duyarlı reseptörleri uyarır. Bu yüzden beyin biberi gerçekten sıcakmış gibi algılar." },
  { id: "p09-130", k: "Vücut", s: "Nanenin ağızda serinlik hissi yaratmasını sağlayan madde hangisidir?", d: "Mentol", y: ["Kapsaisin", "Kafein"], a: "Mentol, soğuğu algılayan reseptörleri uyarır; ağızdaki sıcaklık değişmese de serinlik hissedilir." },
  { id: "p09-131", k: "Vücut", s: "Tat tomurcuklarındaki tat hücrelerinin ortalama ömrü yaklaşık ne kadardır?", d: "Yaklaşık 1-2 hafta", y: ["Ömür boyu", "Yaklaşık 10 yıl"], a: "Tat hücreleri sürekli yenilenir. Dili yaktığımızda tat alma bu sayede birkaç gün içinde düzelir." },
  { id: "p09-132", k: "Vücut", s: "Grip olunca yemeklerin tatsız gelmesinin başlıca nedeni nedir?", d: "Koku alınamaz, lezzetin çoğu kokudan gelir", y: ["Tat tomurcukları tamamen ölür", "Tükürük salgısı tamamen kesilir"], a: "Lezzet, tat ile kokunun birleşimidir. Burun tıkanınca yiyeceğin kokusu alınamaz ve yemek yavan gelir." },
  { id: "p09-133", k: "Vücut", s: "Tuzlu tadı esas olarak hangi iyon oluşturur?", d: "Sodyum", y: ["Kalsiyum", "Demir"], a: "Sofra tuzundaki sodyum iyonları tat hücrelerine girerek tuzlu sinyalini başlatır." },
  { id: "p09-134", k: "Vücut", s: "Ekşi tadı oluşturan şey nedir?", d: "Asitler (hidrojen iyonları)", y: ["Şekerler", "Yağlar"], a: "Limon ve sirke gibi asitli yiyeceklerdeki hidrojen iyonları ekşi tadı algılayan hücreleri uyarır." },
  { id: "p09-135", k: "Vücut", s: "Acı tadı algılamanın evrimsel işlevi olarak en çok hangisi gösterilir?", d: "Olası zehirlere karşı uyarı", y: ["Enerji kaynağını bulmak", "Tuz ihtiyacını bildirmek"], a: "Birçok bitki zehiri acı tadlıdır. Acıya duyarlılık, zararlı olabilecek şeyleri yemeden önce fark etmemizi sağlar." },
  { id: "p09-136", k: "Vücut", s: "Bir maddenin tadını alabilmemiz için önce ne olması gerekir?", d: "Tükürükte çözünmesi", y: ["Isınması", "Dişlerle tamamen öğütülmesi"], a: "Tat molekülleri tükürükte çözünerek tat tomurcuklarındaki hücrelere ulaşır. Kupkuru bir dil tat almakta zorlanır." },
  { id: "p09-137", k: "Vücut", s: "Koku alma reseptörleri burnun neresinde bulunur?", d: "Burun boşluğunun üst kısmında", y: ["Burun deliklerinin ucunda", "Boğazın arka duvarında"], a: "Koku alma epiteli burun boşluğunun tavanında, küçük bir alandadır. Koklarken havayı içe çekmek kokuyu buraya taşır." },
  { id: "p09-138", k: "Vücut", s: "İnsanda yaklaşık kaç çeşit işlevsel koku reseptörü bulunur?", d: "Yaklaşık 400", y: ["Yaklaşık 4", "Yaklaşık 40.000"], a: "Yaklaşık 400 reseptör tipiyle çok sayıda kokuyu ayırt ederiz; her koku birden çok reseptörün birlikte uyarılmasıyla tanınır." },
  { id: "p09-139", k: "Vücut", s: "Koku reseptörlerini keşfettikleri için 2004 Nobel Tıp Ödülü'nü alan bilim insanları kimlerdir?", d: "Richard Axel ve Linda Buck", y: ["James Watson ve Francis Crick", "Frederick Banting ve Charles Best"], a: "Axel ve Buck 1991'de koku reseptörlerini kodlayan büyük gen ailesini tanımladı." },
  { id: "p09-140", k: "Vücut", s: "Kokuların eski anıları güçlü biçimde uyandırmasının nedeni olarak ne gösterilir?", d: "Koku yolunun duygu ve bellek bölgelerine yakınlığı", y: ["Burun kıllarının anıları saklaması", "Kokunun gözleri uyarması"], a: "Koku sinyalleri talamusa uğramadan amigdala ve hipokampus gibi duygu ve bellek bölgelerine ulaşır." },
  { id: "p09-141", k: "Vücut", s: "Burundan gelen koku sinyallerinin beyinde ilk işlendiği yapı hangisidir?", d: "Koku soğanı", y: ["Beyincik", "Hipofiz"], a: "Koku soğanı alın lobunun altındadır; burundan gelen sinyalleri işleyip beynin diğer bölgelerine gönderir." },
  { id: "p09-142", k: "Vücut", s: "Koku alma duyusunun tamamen kaybına ne ad verilir?", d: "Anosmi", y: ["Afazi", "Amnezi"], a: "Anosmi soğuk algınlığı, kafa travması ya da bazı virüs enfeksiyonlarından sonra görülebilir." },
  { id: "p09-143", k: "Vücut", s: "COVID-19 salgınında dikkat çeken belirtilerden biri hangisiydi?", d: "Ani koku kaybı", y: ["Renk körlüğü", "Kulak kiri artışı"], a: "Birçok COVID-19 hastasında burun tıkanıklığı olmadan ani koku ve tat kaybı görüldü; çoğu zaman haftalar içinde düzeldi." },
  { id: "p09-144", k: "Vücut", s: "Burundaki koku alıcı nöronlar için hangisi doğrudur?", d: "Yetişkinlikte de yenilenirler", y: ["Doğuştan sayıları sabittir", "Yalnız uykuda çalışırlar"], a: "Koku alıcı nöronlar dış ortama açık oldukları için hasar görür, ama kök hücrelerden sürekli yenilenirler." },
  { id: "p09-145", k: "Vücut", s: "Bir odaya girince fark ettiğimiz kokuyu bir süre sonra neden algılamayız?", d: "Duyusal alışma (adaptasyon)", y: ["Koku tamamen kaybolur", "Burun kendiliğinden tıkanır"], a: "Değişmeyen bir uyarana karşı reseptörlerin ve beynin tepkisi azalır. Böylece yeni kokuları fark etmek kolaylaşır." },
  { id: "p09-146", k: "Vücut", s: "Vücudun en büyük organı hangisidir?", d: "Deri", y: ["Karaciğer", "Beyin"], a: "Yetişkinde deri birkaç kilogram ağırlığında ve yaklaşık 2 metrekare yüzey alanındadır. En büyük iç organ ise karaciğerdir." },
  { id: "p09-147", k: "Vücut", s: "Parmak uçlarında hafif dokunmayı algılayan duyu cisimciklerinin adı nedir?", d: "Meissner cisimcikleri", y: ["Langerhans adacıkları", "Purkinje lifleri"], a: "Meissner cisimcikleri derinin yüzeye yakın kısmındadır; özellikle parmak ucu ve dudaklarda yoğundur." },
  { id: "p09-148", k: "Vücut", s: "Deride titreşimi ve derin basıncı algılayan soğan katmanlı cisimciklere ne denir?", d: "Pacini cisimcikleri", y: ["Ranvier boğumları", "Peyer plakları"], a: "Pacini cisimcikleri soğan gibi katmanlıdır ve özellikle hızlı titreşimlere çok duyarlıdır." },
  { id: "p09-149", k: "Vücut", s: "Gözlerin kapalıyken kolunun nerede olduğunu bilmeni sağlayan duyuya ne ad verilir?", d: "Propriosepsiyon (konum duyusu)", y: ["Sinestezi", "Nosisepsiyon"], a: "Kas, tendon ve eklemlerdeki reseptörler beyne sürekli konum bilgisi gönderir; bu sayede bakmadan burnumuza dokunabiliriz." },
  { id: "p09-150", k: "Vücut", s: "\"İnsanın yalnızca beş duyusu vardır\" görüşü için ne söylenebilir?", d: "Basitleştirmedir, başka duyular da var", y: ["Kesin bir bilimsel gerçektir", "Yalnız yetişkinler için doğrudur"], a: "Klasik beş duyuya ek olarak denge, konum duyusu, sıcaklık ve ağrı gibi ayrı duyu sistemlerimiz de vardır." },
  { id: "p09-151", k: "Vücut", s: "Kesilmiş bir uzvu hâlâ varmış gibi hissetmeye ne ad verilir?", d: "Hayalet (fantom) uzuv", y: ["Sinestezi", "Refleks yayı"], a: "Beyindeki vücut haritası uzuv kaybından sonra da etkin kalır. Bu yüzden bazı kişiler kayıp uzuvda ağrı bile hissedebilir." },
  { id: "p09-152", k: "Vücut", s: "Sesleri renkli görmek gibi bir duyunun başka bir duyuyu da tetiklemesine ne denir?", d: "Sinestezi", y: ["Anosmi", "Propriosepsiyon"], a: "Sinestezide örneğin harfler ya da sayılar belirli renklerle birlikte algılanır. Bir hastalık değil, algının bir çeşididir." },
  { id: "p09-153", k: "Vücut", s: "Deride sıcaklık değişimlerini algılayan reseptörlere ne ad verilir?", d: "Termoreseptörler", y: ["Fotoreseptörler", "Baroreseptörler"], a: "Deride sıcağı ve soğuğu algılayan ayrı reseptörler vardır; sıcaklığı tek bir noktadan değil, bu iki sistemden algılarız." },
  { id: "p09-154", k: "Vücut", s: "İnsanların kendi kendini gıdıklayamamasının en yaygın açıklaması nedir?", d: "Beyin kendi hareketinin sonucunu önceden tahmin eder", y: ["Parmaklarda dokunma reseptörü yoktur", "Deri kendi dokunuşuna alışkındır"], a: "Beyin kendi hareketlerimizin yaratacağı hissi önceden hesaplar ve tepkiyi bastırır; sürpriz olmayınca gıdıklanma da olmaz." },
  { id: "p09-155", k: "Vücut", s: "Görme engellilerin dokunarak okuduğu kabartma yazı sistemini geliştiren kimdir?", d: "Louis Braille", y: ["Helen Keller", "Samuel Morse"], a: "Küçük yaşta görme yetisini kaybeden Louis Braille, bu kabartma nokta sistemini 1820'lerde, henüz gençken geliştirdi." },
  { id: "p09-156", k: "Vücut", s: "George Miller'ın 1956 tarihli ünlü makalesine göre kısa süreli bellek kaç öğe tutabilir?", d: "Yaklaşık 7 (artı-eksi 2)", y: ["Yaklaşık 70", "Yaklaşık 700"], a: "Miller \"sihirli sayı yedi\" fikrini ortaya attı. Daha yeni çalışmalar gerçek kapasitenin dört öğe civarında olabileceğini öne sürüyor." },
  { id: "p09-157", k: "Vücut", s: "Kendi üzerinde deneyler yaparak \"unutma eğrisi\"ni ortaya koyan Alman psikolog kimdir?", d: "Hermann Ebbinghaus", y: ["Ivan Pavlov", "Sigmund Freud"], a: "Ebbinghaus anlamsız heceleri ezberleyip unutma hızını ölçtü. Öğrenilenlerin büyük kısmının ilk gün içinde hızla unutulduğunu gösterdi." },
  { id: "p09-158", k: "Vücut", s: "Köpeklerin zil sesiyle salya akıtmayı öğrenmesini gösteren bilim insanı kimdir?", d: "Ivan Pavlov", y: ["B. F. Skinner", "Hermann Ebbinghaus"], a: "Pavlov'un çalışmaları klasik koşullanmanın temelini attı: nötr bir uyaran, ödülle eşleşince tek başına tepki doğurabilir." },
  { id: "p09-159", k: "Vücut", s: "Ivan Pavlov 1904 Nobel Ödülü'nü hangi çalışmasıyla aldı?", d: "Sindirim fizyolojisi", y: ["Koşullu refleksler", "Uyku araştırmaları"], a: "Pavlov'u ünlü yapan koşullanma deneyleriydi, ama Nobel'i sindirim bezleri üzerine yaptığı çalışmalarla kazandı." },
  { id: "p09-160", k: "Vücut", s: "Davranışın ödül ve cezayla şekillendiği edimsel koşullanmayı \"kutu\" deneyleriyle inceleyen psikolog kimdir?", d: "B. F. Skinner", y: ["Ivan Pavlov", "Carl Jung"], a: "Skinner kutusunda bir kola basan hayvan yem ödülü alır. Ödüllendirilen davranışın tekrarlanma olasılığı artar." },
  { id: "p09-161", k: "Vücut", s: "Bilgiyi uzun süre akılda tutmak için araştırmaların en güçlü biçimde desteklediği yöntem hangisidir?", d: "Tekrarları zamana yaymak", y: ["Hepsini tek oturumda çalışmak", "Metni yalnız bir kez okumak"], a: "Aralıklı tekrar etkisi bir asrı aşkın süredir tekrar tekrar gösterilmiştir. Aynı süreyi günlere yaymak kalıcılığı artırır." },
  { id: "p09-162", k: "Vücut", s: "Araştırmalara göre öğrendiğini kalıcı kılmada yeniden okumaktan daha etkili olan hangisidir?", d: "Kendini sınamak", y: ["Metnin altını çizmek", "Metni yüksek sesle kopyalamak"], a: "Bilgiyi hatırlamaya çalışmak belleği güçlendirir. Buna sınama etkisi denir ve birçok deneyle gösterilmiştir." },
  { id: "p09-163", k: "Vücut", s: "Uykunun öğrendiklerimiz üzerindeki etkisi için hangisi doğrudur?", d: "Anıların pekişmesine yardım eder", y: ["Yeni anıları siler", "Bellek üzerinde etkisi yoktur"], a: "Uyku sırasında gün içinde öğrenilenler yeniden işlenir ve kalıcı belleğe aktarılır. Uykusuzluk öğrenmeyi zorlaştırır." },
  { id: "p09-164", k: "Vücut", s: "Yıllarca binmesen de bisiklet sürmeyi unutmamanı sağlayan bellek türü hangisidir?", d: "İşlemsel (prosedürel) bellek", y: ["Anlamsal bellek", "Duyusal bellek"], a: "Beceri ve alışkanlıklar işlemsel bellekte tutulur. Bu bellek bilinçli düşünmeden çalışır ve unutulmaya dirençlidir." },
  { id: "p09-165", k: "Vücut", s: "Ankara'nın Türkiye'nin başkenti olduğu gibi genel bilgileri tuttuğumuz bellek türü hangisidir?", d: "Anlamsal bellek", y: ["Olaysal bellek", "İşlemsel bellek"], a: "Anlamsal bellek kavramları ve olguları saklar; bu bilgiyi nerede ve ne zaman öğrendiğimizi çoğu zaman hatırlamayız." },
  { id: "p09-166", k: "Vücut", s: "Geçen doğum gününde yaşadıklarını hatırlaman hangi bellek türüne örnektir?", d: "Olaysal (epizodik) bellek", y: ["İşlemsel bellek", "Duyusal bellek"], a: "Olaysal bellek, belirli bir yer ve zamanda yaşadığımız kişisel deneyimleri saklar." },
  { id: "p09-167", k: "Vücut", s: "Hipokampusları ameliyatla çıkarıldıktan sonra yeni uzun süreli anı oluşturamayan ünlü hasta kimdir?", d: "Henry Molaison (H.M.)", y: ["Phineas Gage", "Louis Braille"], a: "1953'teki epilepsi ameliyatından sonra H.M. yeni olayları hatırlayamadı, ama yeni beceriler öğrenebildi. Bu vaka bellek türlerinin ayrı olduğunu gösterdi." },
  { id: "p09-168", k: "Vücut", s: "Bir beyin hasarından sonra yeni anılar oluşturamama durumuna ne ad verilir?", d: "İleriye dönük (anterograd) amnezi", y: ["Geriye dönük (retrograd) amnezi", "Afazi"], a: "Anterograd amnezide eski anılar büyük ölçüde korunabilir, ama yeni bilgiler kalıcı belleğe aktarılamaz." },
  { id: "p09-169", k: "Vücut", s: "Çoğu insanın yaklaşık 3 yaşından önceki olayları hatırlayamamasına ne denir?", d: "Bebeklik amnezisi", y: ["Alzheimer hastalığı", "Déjà vu"], a: "Bebeklik amnezisi evrenseldir. Bu dönemde beynin, özellikle hipokampusun, hâlâ hızla gelişmesiyle ilişkilendirilir." },
  { id: "p09-170", k: "Vücut", s: "Yaşanmamış olaylara ait sahte anıların kolayca oluşturulabildiğini gösteren psikolog kimdir?", d: "Elizabeth Loftus", y: ["Marie Curie", "Margaret Mead"], a: "Loftus'un deneyleri, yönlendirici soruların tanıkların anılarını değiştirebildiğini gösterdi." },
  { id: "p09-171", k: "Vücut", s: "Anılarımızın bir kamera kaydı gibi değişmeden saklandığı fikri için ne söylenebilir?", d: "Yanlıştır, anılar hatırlandıkça yeniden kurulur", y: ["Doğrudur, hiçbir ayrıntı değişmez", "Yalnız çocukluk anıları için doğrudur"], a: "Her hatırlayışta anı yeniden oluşturulur ve bu sırada değişebilir. Bu yüzden kendimizden çok emin olduğumuz anılar bile hatalı olabilir." },
  { id: "p09-172", k: "Vücut", s: "\"Birlikte ateşlenen nöronlar birbirine bağlanır\" fikriyle bilinen psikolog kimdir?", d: "Donald Hebb", y: ["Ivan Pavlov", "Carl Jung"], a: "Hebb 1949'da, iki nöron sık sık birlikte etkinleşirse aralarındaki bağlantının güçleneceğini öne sürdü." },
  { id: "p09-173", k: "Vücut", s: "Öğrenmenin hücresel temeli sayılan, sinapsların uzun süre güçlenmesine ne denir?", d: "Uzun süreli güçlenme (LTP)", y: ["Fotosentez", "Mitoz bölünme"], a: "Uzun süreli güçlenme ilk kez 1970'lerin başında tavşan hipokampusunda gösterildi." },
  { id: "p09-174", k: "Vücut", s: "Bir telefon numarasını tuşlayana kadar aklında tutarken hangi belleği kullanırsın?", d: "Çalışma belleği", y: ["İşlemsel bellek", "Anlamsal bellek"], a: "Çalışma belleği bilgiyi kısa süre aklımızda tutup üzerinde işlem yapmamızı sağlar; kapasitesi sınırlıdır." },
  { id: "p09-175", k: "Vücut", s: "Yeni bir durumu daha önce aynen yaşamış gibi hissetmeye ne denir?", d: "Déjà vu", y: ["Jamais vu", "Sinestezi"], a: "Déjà vu Fransızcada \"daha önce görülmüş\" demektir. Sağlıklı insanların çoğu bunu zaman zaman yaşar." },
  { id: "p09-176", k: "Vücut", s: "Uzun bir numarayı küçük parçalara bölerek daha kolay hatırlamaya ne denir?", d: "Gruplama", y: ["Bastırma", "Unutma"], a: "Gruplama sayesinde 0532 456 78 90 gibi bir numarayı tek tek rakamlar yerine birkaç parça olarak aklımızda tutarız." },
  { id: "p09-177", k: "Vücut", s: "Londra taksi şoförleri üzerinde yapılan ünlü beyin taraması çalışması ne buldu?", d: "Hipokampusun arka kısmı daha büyüktü", y: ["Beyinleri genel olarak küçülmüştü", "Görme korteksleri daha büyüktü"], a: "Karmaşık şehir haritasını ezberleyen şoförlerde uzamsal bellekle ilişkili bu bölge, kontrol grubuna göre daha büyük bulundu." },
  { id: "p09-178", k: "Vücut", s: "Uykuyu düzenleyen melatonin hormonunu salgılayan bez hangisidir?", d: "Epifiz (pineal) bezi", y: ["Tiroid bezi", "Hipofiz bezi"], a: "Epifiz bezi beynin ortasında, nohut tanesinden küçük bir bezdir. Karanlıkta melatonin salgılar." },
  { id: "p09-179", k: "Vücut", s: "Melatonin salgısı en çok ne zaman artar?", d: "Akşam, hava karardıktan sonra", y: ["Öğle saatlerinde", "Sabah uyanınca"], a: "Işık melatonin salgısını baskılar. Karanlık çökünce düzeyi yükselir ve vücut uykuya hazırlanır." },
  { id: "p09-180", k: "Vücut", s: "Vücudun ana biyolojik saati beynin hangi bölgesinde bulunur?", d: "Suprakiazmatik çekirdek", y: ["Hipokampus", "Beyincik"], a: "Hipotalamustaki bu küçük çekirdek, gözlerden gelen ışık bilgisiyle vücudun günlük ritmini ayarlar." },
  { id: "p09-181", k: "Vücut", s: "Biyolojik saati her gün yeniden ayarlayan en güçlü dış etken hangisidir?", d: "Işık", y: ["Ses", "Hava nemi"], a: "Gözlere ulaşan ışık, özellikle sabah ışığı, biyolojik saati 24 saatlik güne uydurur." },
  { id: "p09-182", k: "Vücut", s: "\"Sirkadiyen\" ritim adı ne anlama gelir?", d: "Yaklaşık bir gün", y: ["Yaklaşık bir hafta", "Yaklaşık bir ay"], a: "Latince \"circa\" (yaklaşık) ve \"dies\" (gün) kelimelerinden gelir. Bu ritimler kabaca 24 saatlik döngüler izler." },
  { id: "p09-183", k: "Vücut", s: "2017 Nobel Tıp Ödülü hangi keşif için verildi?", d: "Biyolojik saatin moleküler mekanizması", y: ["Hepatit C virüsünün keşfi", "Penisilinin keşfi"], a: "Jeffrey Hall, Michael Rosbash ve Michael Young, meyve sineklerinde günlük ritmi yöneten genleri ve proteinleri çözdü." },
  { id: "p09-184", k: "Vücut", s: "Biyolojik saate ışık bilgisini taşıyan özel retina hücreleri hangi pigmenti kullanır?", d: "Melanopsin", y: ["Melanin", "Hemoglobin"], a: "Bu hücreler görüntü oluşturmaz; ortamın ne kadar aydınlık olduğunu algılayıp biyolojik saate bildirir." },
  { id: "p09-185", k: "Vücut", s: "Akşam saatlerinde hangi renkteki ışık melatonin salgısını en çok baskılar?", d: "Mavi", y: ["Kırmızı", "Turuncu"], a: "Melanopsin en çok kısa dalga boylu mavi ışığa duyarlıdır. Bu yüzden akşam parlak beyaz ve mavi ışık uykuyu geciktirebilir." },
  { id: "p09-186", k: "Vücut", s: "Canlı ve hikâyeli rüyaların en sık görüldüğü uyku evresi hangisidir?", d: "REM uykusu", y: ["Derin (yavaş dalga) uyku", "Uykuya dalış evresi"], a: "Rüyalar diğer evrelerde de görülebilir, ama canlı ve hikâyeli rüyalar en çok REM uykusunda yaşanır." },
  { id: "p09-187", k: "Vücut", s: "REM uykusundaki \"REM\" kısaltması neyi anlatır?", d: "Hızlı göz hareketlerini", y: ["Yavaş beyin dalgalarını", "Derin kas gevşemesini"], a: "REM, İngilizce \"rapid eye movement\" yani hızlı göz hareketi demektir; bu evrede gözler kapakların altında hızla hareket eder." },
  { id: "p09-188", k: "Vücut", s: "REM uykusu sırasında vücudun büyük kaslarına ne olur?", d: "Geçici olarak gevşeyip hareketsiz kalır", y: ["Sürekli kasılı kalır", "Ritmik olarak titrer"], a: "REM'de beyin çok etkindir ama büyük kaslar geçici olarak felçli gibidir. Bu, rüyaları canlandırmamızı önler." },
];
